SELECT id, type_code, name, sort_order, status, source_template_version, version
FROM public.iam_org_type
WHERE tenant_id = #{tenantId}
  AND is_deleted = false

  AND status = #{status}

ORDER BY sort_order, id
OFFSET #{offset} LIMIT #{limit}

