FROM public.iam_org_type
WHERE tenant_id = #{tenantId}
  AND id = #{typeId}
  AND is_deleted = false
LIMIT 1

mapper.insert:
INSERT INTO public.iam_org_type (
    tenant_id, type_code, name, sort_order, status, source_template_version,
    created_by, updated_by
) VALUES (
    #{tenantId}, #{typeCode}, #{name}, #{sortOrder}, #{status}, #{sourceTemplateVersion},
    #{createdBy}, #{updatedBy}
)

mapper.update:
UPDATE public.iam_org_type
SET name = #{name},
    sort_order = #{sortOrder},
    updated_by = #{operatorId},
    updated_time = CURRENT_TIMESTAMP,
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{typeId}
  AND version = #{version}
  AND is_deleted = false

UPDATE public.iam_org_type
SET status = #{status},
    updated_by = #{operatorId},
    updated_time = CURRENT_TIMESTAMP,
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{typeId}
  AND version = #{version}
  AND status <> #{status}
  AND is_deleted = false

