INSERT INTO public.iam_org_code_registry (
    tenant_id, normalized_code, organization_id, created_by, updated_by
) VALUES (
    #{tenantId}, #{normalizedCode}, #{organizationId}, #{operatorId}, #{operatorId}
)

INSERT INTO public.iam_organization_closure (
    tenant_id, ancestor_id, descendant_id, depth, created_by, updated_by
)
SELECT #{tenantId}, ancestor_id, #{organizationId}, depth + 1, #{operatorId}, #{operatorId}
FROM public.iam_organization_closure
WHERE tenant_id = #{tenantId}
  AND descendant_id = #{parentId}
  AND is_deleted = false
UNION ALL
SELECT #{tenantId}, #{organizationId}, #{organizationId}, 0, #{operatorId}, #{operatorId}

INSERT INTO public.iam_org_name_history (
    tenant_id, organization_id, old_name, new_name, changed_by, created_by, updated_by
) VALUES (
    #{tenantId}, #{organizationId}, #{oldName}, #{newName}, #{operatorId}, #{operatorId}, #{operatorId}
)

