WHERE tenant_id = #{tenantId}
  AND parent_id = #{organizationId}
  AND is_deleted = false
ORDER BY org_type_id

SELECT COUNT(1)
FROM public.iam_organization_closure
WHERE tenant_id = #{tenantId}
  AND ancestor_id = #{ancestorId}
  AND descendant_id = #{descendantId}
  AND is_deleted = false

mapper.insert:
INSERT INTO public.iam_organization_closure (
    tenant_id, ancestor_id, descendant_id, depth, created_by, updated_by
)
SELECT #{tenantId}, super_path.ancestor_id, subtree.descendant_id,
       super_path.depth + subtree.depth + 1, #{operatorId}, #{operatorId}
FROM public.iam_organization_closure super_path
CROSS JOIN public.iam_organization_closure subtree
WHERE super_path.tenant_id = #{tenantId}
  AND super_path.descendant_id = #{newParentId}
  AND super_path.is_deleted = false
  AND subtree.tenant_id = #{tenantId}
  AND subtree.ancestor_id = #{organizationId}
  AND subtree.is_deleted = false

mapper.update:
UPDATE public.iam_organization
SET own_status = #{status},
    path_version = path_version + 1,
    updated_by = #{operatorId},
    updated_time = CURRENT_TIMESTAMP,
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{organizationId}
  AND parent_id IS NOT NULL
  AND own_status <> #{status}
  AND version = #{version}
  AND is_deleted = false

mapper.select:
SELECT
    (SELECT COUNT(1) FROM public.iam_organization child
     WHERE child.tenant_id = #{tenantId} AND child.parent_id = #{organizationId}
       AND child.is_deleted = false)
  + (SELECT COUNT(1) FROM public.iam_account account
     WHERE account.tenant_id = #{tenantId} AND account.organization_id = #{organizationId}
       AND account.is_deleted = false)
  + (SELECT COUNT(1) FROM public.iam_role role
     WHERE role.tenant_id = #{tenantId} AND role.organization_id = #{organizationId}
       AND role.is_deleted = false)
  + (SELECT COUNT(1) FROM public.iam_org_owner owner
     WHERE owner.tenant_id = #{tenantId} AND owner.organization_id = #{organizationId}
       AND owner.is_deleted = false)

mapper.update:
UPDATE public.iam_organization
SET is_deleted = true,
    updated_by = #{operatorId},
    updated_time = CURRENT_TIMESTAMP,
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{organizationId}
  AND parent_id IS NOT NULL
  AND version = #{version}
  AND is_deleted = false
